-- Project : India Lake Water Quality Analytics (CPCB NWMP 2017-2022)
-- Database: data/lakes.db  (generated by etl/clean_lakes.py)
-- Contents: Q1-Q3b basic counts | Q4-Q5 state & lake rankings
--           Q5b-Q5f coliform outlier checks | Q6 YoY spike detection (LAG)




-- Q1: Number of monitoring stations per state
SELECT state, COUNT(*) AS station_count
FROM dim_station
GROUP BY state
ORDER BY station_count DESC;

-- Query 2: Stations by water body type
SELECT water_body_type, COUNT(*) AS station_count
FROM dim_station
GROUP BY water_body_type
ORDER BY station_count DESC;

-- Query 3: Year-wise station records
SELECT year, COUNT(DISTINCT stn_code) AS station_count
FROM fact_lake_quality
WHERE year BETWEEN 2017 AND 2022
GROUP BY year
ORDER by year;

-- Query 3b: Stations grouped by number of years monitored

SELECT years_monitored, COUNT(*) AS station_count
FROM dim_station
WHERE years_monitored BETWEEN 1 AND 6
GROUP BY years_monitored
ORDER BY years_monitored;

--Query 4 State-wise average of max BOD 
SELECT d.state, 
	ROUND(AVG(f.bod_mg_l_max), 2) AS avg_max_bod, 
	COUNT(*) AS records
FROM fact_lake_quality f
JOIN dim_station d ON f.stn_code = d.stn_code
WHERE f.bod_mg_l_max IS NOT NULL
GROUP BY d.state
HAVING COUNT(*) >= 10
ORDER BY avg_max_bod DESC;

-- Query 5: Top 10 lakes by maximum fecal coliform

SELECT d.station_name, d.state, d.water_body_type,
       MAX(f.fecal_coliform_mpn_max) AS max_fecal_coliform
FROM fact_lake_quality f
JOIN dim_station d
    ON f.stn_code = d.stn_code
WHERE f.fecal_coliform_mpn_max IS NOT NULL
GROUP BY
    d.stn_code,
    d.station_name,
    d.state,
    d.water_body_type
ORDER BY max_fecal_coliform DESC
LIMIT 10;

-- Q5b: Sanity check on the top station across years
SELECT year,
       fecal_coliform_mpn_min,
       fecal_coliform_mpn_max,
       total_coliform_mpn_max
FROM fact_lake_quality
WHERE stn_code = (SELECT stn_code FROM dim_station
                  WHERE station_name LIKE 'HOSAKEREHALLI%')
ORDER BY year;

-- Q5c: Annual count of records with fecal coliform above 10 crore
SELECT f.year,
    COUNT(*) AS high_fecal_coliform_records
FROM fact_lake_quality f
WHERE f.fecal_coliform_mpn_max > 100000000
  AND f.year BETWEEN 2017 AND 2022
GROUP BY f.year
ORDER BY f.year;


-- Q5d:
SELECT d.station_name, d.state, f.year,
       f.fecal_coliform_mpn_min,
       f.fecal_coliform_mpn_max,
       f.total_coliform_mpn_max
FROM fact_lake_quality f
JOIN dim_station d ON f.stn_code = d.stn_code
WHERE f.fecal_coliform_mpn_max > 100000000
ORDER BY f.fecal_coliform_mpn_max DESC;


-- Q5e: Top 10 most frequently repeated total coliform values
SELECT
    total_coliform_mpn_max,
    COUNT(*) AS times_repeated
FROM fact_lake_quality
WHERE total_coliform_mpn_max IS NOT NULL
GROUP BY total_coliform_mpn_max
HAVING COUNT(*) >= 2
ORDER BY total_coliform_mpn_max DESC
LIMIT 10;

-- Q5f: Most frequently repeated total coliform values overall
SELECT total_coliform_mpn_max,
       COUNT(*) AS times_repeated
FROM fact_lake_quality
WHERE total_coliform_mpn_max IS NOT NULL
GROUP BY total_coliform_mpn_max
ORDER BY times_repeated DESC
LIMIT 10;

-- Query 6: Detect year-over-year spikes greater than 100x

WITH yearly AS (
    SELECT
        stn_code,
        year,
        fecal_coliform_mpn_max,
        LAG(fecal_coliform_mpn_max) OVER (
            PARTITION BY stn_code
            ORDER BY year
        ) AS prev_year_value
    FROM fact_lake_quality
    WHERE fecal_coliform_mpn_max IS NOT NULL
)
SELECT
    stn_code,
    year,
    prev_year_value,
    fecal_coliform_mpn_max AS current_year_value,
    ROUND(
        1.0 * fecal_coliform_mpn_max / prev_year_value,
        2
    ) AS spike_ratio
FROM yearly
WHERE prev_year_value > 0
  AND fecal_coliform_mpn_max > prev_year_value * 100
ORDER BY spike_ratio DESC;

-- Query 6: Detect potential fecal coliform spikes
-- Threshold: >100x, with previous value >= 1000
-- Minimum baseline reduces misleading ratios from tiny denominators.

WITH yearly AS (
    SELECT
        stn_code,
        year,
        fecal_coliform_mpn_max,
        LAG(year) OVER (
            PARTITION BY stn_code
            ORDER BY year
        ) AS prev_year,
        LAG(fecal_coliform_mpn_max) OVER (
            PARTITION BY stn_code
            ORDER BY year
        ) AS prev_year_value
    FROM fact_lake_quality
    WHERE fecal_coliform_mpn_max IS NOT NULL
)
SELECT
    d.station_name,
    d.state,
    y.stn_code,
    y.prev_year,
    y.year,
    y.year - y.prev_year AS gap_years,
    y.prev_year_value,
    y.fecal_coliform_mpn_max AS current_year_value,
    ROUND(
        1.0 * y.fecal_coliform_mpn_max / y.prev_year_value,
        2
    ) AS spike_ratio
FROM yearly y
JOIN dim_station d
    ON y.stn_code = d.stn_code
WHERE y.prev_year_value >= 1000
  AND y.fecal_coliform_mpn_max > y.prev_year_value * 100
ORDER BY spike_ratio DESC;